package dragonboat

import (
	"encoding/json"
	"errors"
	"math"
	"sync"
	"testing"

	"github.com/lni/dragonboat/v3/config"
	dragonraft "github.com/lni/dragonboat/v3/internal/raft"
	pb "github.com/lni/dragonboat/v3/raftpb"
)

var (
	errAssuranceCompacted   = errors.New("assurance log compacted")
	errAssuranceOutOfDate   = errors.New("assurance snapshot out of date")
	errAssuranceUnavailable = errors.New("assurance log unavailable")
)

type assuranceLogDB struct {
	entries     []pb.Entry
	markerIndex uint64
	markerTerm  uint64
	snapshot    pb.Snapshot
	state       pb.State
}

func newAssuranceLogDB() *assuranceLogDB {
	return &assuranceLogDB{}
}

func (db *assuranceLogDB) firstIndex() uint64 {
	return db.markerIndex + 1
}

func (db *assuranceLogDB) lastIndex() uint64 {
	return db.markerIndex + uint64(len(db.entries))
}

func (db *assuranceLogDB) GetRange() (uint64, uint64) {
	return db.firstIndex(), db.lastIndex()
}

func (db *assuranceLogDB) SetRange(index uint64, length uint64) {}

func (db *assuranceLogDB) NodeState() (pb.State, pb.Membership) {
	return db.state, db.snapshot.Membership
}

func (db *assuranceLogDB) SetState(state pb.State) {
	db.state = state
}

func (db *assuranceLogDB) CreateSnapshot(snapshot pb.Snapshot) error {
	if db.snapshot.Index >= snapshot.Index {
		return errAssuranceOutOfDate
	}
	db.snapshot = snapshot
	return nil
}

func (db *assuranceLogDB) ApplySnapshot(snapshot pb.Snapshot) error {
	if db.snapshot.Index >= snapshot.Index {
		return errAssuranceOutOfDate
	}
	db.snapshot = snapshot
	db.markerIndex = snapshot.Index
	db.markerTerm = snapshot.Term
	db.entries = nil
	return nil
}

func (db *assuranceLogDB) Term(index uint64) (uint64, error) {
	if index == 0 {
		return 0, nil
	}
	if index == db.markerIndex {
		return db.markerTerm, nil
	}
	if index < db.firstIndex() {
		return 0, errAssuranceCompacted
	}
	if index > db.lastIndex() {
		return 0, errAssuranceUnavailable
	}
	return db.entries[index-db.firstIndex()].Term, nil
}

func (db *assuranceLogDB) Entries(low uint64, high uint64, maxSize uint64) ([]pb.Entry, error) {
	if low <= db.markerIndex {
		return nil, errAssuranceCompacted
	}
	if high > db.lastIndex()+1 {
		return nil, errAssuranceUnavailable
	}
	if low >= high {
		return nil, nil
	}
	entries := append([]pb.Entry(nil), db.entries[low-db.firstIndex():high-db.firstIndex()]...)
	if maxSize == math.MaxUint64 || len(entries) == 0 {
		return entries, nil
	}
	total := 0
	for i := range entries {
		total += entries[i].SizeUpperLimit()
		if uint64(total) > maxSize {
			return entries[:i], nil
		}
	}
	return entries, nil
}

func (db *assuranceLogDB) Snapshot() pb.Snapshot {
	return db.snapshot
}

func (db *assuranceLogDB) Compact(index uint64) error {
	return nil
}

func (db *assuranceLogDB) Append(entries []pb.Entry) error {
	if len(entries) == 0 {
		return nil
	}
	offset := entries[0].Index - db.markerIndex
	if uint64(len(db.entries)+1) > offset {
		db.entries = db.entries[:offset-1]
	}
	db.entries = append(db.entries, entries...)
	return nil
}

type assuranceCluster struct {
	peers   map[uint64]*dragonraft.Peer
	logs    map[uint64]*assuranceLogDB
	applied map[uint64]uint64
	commit  map[uint64]uint64
	ready   map[uint64][]pb.ReadyToRead
}

func newAssuranceCluster(t *testing.T) *assuranceCluster {
	t.Helper()
	c := &assuranceCluster{
		peers:   make(map[uint64]*dragonraft.Peer),
		logs:    make(map[uint64]*assuranceLogDB),
		applied: make(map[uint64]uint64),
		commit:  make(map[uint64]uint64),
		ready:   make(map[uint64][]pb.ReadyToRead),
	}
	addresses := []dragonraft.PeerAddress{
		{NodeID: 1, Address: "assurance-1"},
		{NodeID: 2, Address: "assurance-2"},
		{NodeID: 3, Address: "assurance-3"},
	}
	for id := uint64(1); id <= 3; id++ {
		db := newAssuranceLogDB()
		cfg := config.Config{
			ClusterID:       7,
			NodeID:          id,
			ElectionRTT:     10,
			HeartbeatRTT:    1,
			MaxInMemLogSize: 0,
		}
		c.logs[id] = db
		c.peers[id] = dragonraft.Launch(cfg, db, nil, addresses, true, true)
		c.applied[id] = uint64(len(addresses))
		c.peers[id].NotifyRaftLastApplied(c.applied[id])
	}
	return c
}

func (c *assuranceCluster) pump(id uint64) []pb.Message {
	update := c.pumpUpdate(id)
	return append([]pb.Message(nil), update.Messages...)
}

func (c *assuranceCluster) pumpUpdate(id uint64) pb.Update {
	update := c.peers[id].GetUpdate(true, c.applied[id])
	c.ready[id] = append(c.ready[id], update.ReadyToReads...)
	if update.State.Commit > c.commit[id] {
		c.commit[id] = update.State.Commit
	}
	if len(update.EntriesToSave) > 0 {
		if err := c.logs[id].Append(update.EntriesToSave); err != nil {
			panic(err)
		}
	}
	c.peers[id].Commit(update)
	return update
}

func (c *assuranceCluster) deliver(message pb.Message) []pb.Message {
	c.peers[message.To].Handle(message)
	return c.pump(message.To)
}

func (c *assuranceCluster) drain(messages []pb.Message) {
	queue := append([]pb.Message(nil), messages...)
	for len(queue) > 0 {
		message := queue[0]
		queue = queue[1:]
		queue = append(queue, c.deliver(message)...)
	}
}

func (c *assuranceCluster) deliverTo(id uint64, messages []pb.Message) []pb.Message {
	var produced []pb.Message
	for _, message := range messages {
		if message.To == id {
			produced = append(produced, c.deliver(message)...)
		}
	}
	return produced
}

func findAssuranceMessage(messages []pb.Message,
	messageType pb.MessageType, to uint64, hint uint64) (pb.Message, bool) {
	for _, message := range messages {
		if message.Type == messageType && message.To == to &&
			(hint == 0 || message.Hint == hint) {
			return message, true
		}
	}
	return pb.Message{}, false
}

func emitObserverEndpointEvent(t *testing.T, event map[string]interface{}) {
	t.Helper()
	b, err := json.Marshal(event)
	if err != nil {
		t.Fatalf("failed to marshal assurance event: %v", err)
	}
	t.Logf("CA_EVENT %s", b)
}

// registerAssuranceObserver records node 4 as an observer in every voter's
// raft membership, which is the state produced by an applied AddObserver
// config change.
func registerAssuranceObserver(t *testing.T, c *assuranceCluster) {
	t.Helper()
	for id := uint64(1); id <= 3; id++ {
		c.peers[id].ApplyConfigChange(pb.ConfigChange{
			Type:    pb.AddObserver,
			NodeID:  4,
			Address: "assurance-4",
		})
		if messages := c.pump(id); len(messages) > 0 {
			c.drain(messages)
		}
	}
	if c.commit[1] < 4 {
		t.Fatalf("observer registration disturbed the leader commit, commit=%d",
			c.commit[1])
	}
}

// newAssuranceObserver launches a real observer Raft peer for node 4. Its log
// DB carries the committed voter membership {1,2,3}, which is what an observer
// learns from the replicated bootstrap entries or a snapshot, and a leader
// heartbeat teaches it the current leader.
func newAssuranceObserver(t *testing.T) *dragonraft.Peer {
	t.Helper()
	db := newAssuranceLogDB()
	db.snapshot.Membership = pb.Membership{
		ConfigChangeId: 1,
		Addresses: map[uint64]string{
			1: "assurance-1",
			2: "assurance-2",
			3: "assurance-3",
		},
	}
	cfg := config.Config{
		ClusterID:       7,
		NodeID:          4,
		ElectionRTT:     10,
		HeartbeatRTT:    1,
		MaxInMemLogSize: 0,
		IsObserver:      true,
	}
	observer := dragonraft.Launch(cfg, db, nil, nil, false, true)
	observer.Handle(pb.Message{
		From: 1,
		To:   4,
		Type: pb.Heartbeat,
		Term: 1,
	})
	update := observer.GetUpdate(true, 0)
	observer.Commit(update)
	return observer
}

// admitObserverRead registers an observer-local ReadIndex request and returns
// the pending-read bookkeeping together with the ReadIndex message that the
// observer's real raft peer forwarded to its leader.
func admitObserverRead(t *testing.T, observer *dragonraft.Peer,
	reads *pendingReadIndex, req *RequestState,
	ctx pb.SystemCtx) pb.Message {
	t.Helper()
	reads.add(ctx, []*RequestState{req})
	observer.ReadIndex(ctx)
	update := observer.GetUpdate(true, 0)
	forwarded := append([]pb.Message(nil), update.Messages...)
	observer.Commit(update)
	message, ok := findAssuranceMessage(forwarded, pb.ReadIndex, 1, ctx.Low)
	if !ok {
		t.Fatalf("observer did not forward its ReadIndex request; messages=%+v",
			forwarded)
	}
	return message
}

// consumeObserverReady feeds the observer peer's real ReadyToRead output into
// the node-level pending read registry and returns the ready index.
func consumeObserverReady(t *testing.T, observer *dragonraft.Peer,
	reads *pendingReadIndex) []pb.ReadyToRead {
	t.Helper()
	update := observer.GetUpdate(true, 0)
	ready := append([]pb.ReadyToRead(nil), update.ReadyToReads...)
	observer.Commit(update)
	reads.addReady(ready)
	return ready
}

func completedFlag(req *RequestState) int {
	select {
	case <-req.CompletedC:
		return 1
	default:
		return 0
	}
}

func TestAssuranceObserverLocalReadIndexCompletion(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}
	registerAssuranceObserver(t, c)
	observer := newAssuranceObserver(t)

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads4 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req4, err := reads4.read(50)
	if err != nil {
		t.Fatalf("failed to create observer read: %v", err)
	}
	ctxA := reads4.nextCtx()
	ctxB := pb.SystemCtx{Low: 202, High: 2003}

	forwardedA := admitObserverRead(t, observer, reads4, req4, ctxA)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "observer_local_readindex_forwarded",
		"request_id": "observer-read-A",
		"node_id":    uint64(4),
		"leader_id":  forwardedA.To,
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})

	// The real leader admits the observer's forwarded request.
	leaderMessagesA := c.deliver(forwardedA)
	// A later voter-originated request is queued behind the observer's request.
	c.peers[3].ReadIndex(ctxB)
	leaderMessagesB := c.deliverTo(1, c.pump(3))
	if len(leaderMessagesB) == 0 {
		t.Fatal("leader produced no confirmation heartbeat for the later context")
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":            "later_voter_readindex_queued",
		"request_id":       "voter-read-B",
		"node_id":          uint64(3),
		"leader_id":        uint64(1),
		"ctx_low":          ctxB.Low,
		"ctx_high":         ctxB.High,
		"admitted_ctx_low": ctxA.Low,
	})

	heartbeatB, ok := findAssuranceMessage(leaderMessagesB, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("no heartbeat carrying the later context was sent to node 3; messages=%+v",
			leaderMessagesB)
	}
	node3Output := c.deliver(heartbeatB)
	leaderReplies := c.deliverTo(1, node3Output)
	observerReply, ok := findAssuranceMessage(leaderReplies, pb.ReadIndexResp, 4, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for observer 4; messages=%+v",
			leaderReplies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "observer_readindex_reply",
		"request_id":         "observer-read-A",
		"reply_to":           observerReply.To,
		"admitted_ctx_low":   ctxA.Low,
		"admitted_ctx_high":  ctxA.High,
		"trigger_from":       uint64(3),
		"trigger_ctx_low":    ctxB.Low,
		"trigger_ctx_high":   ctxB.High,
		"response_ctx_low":   observerReply.Hint,
		"response_ctx_high":  observerReply.HintHigh,
		"response_log_index": observerReply.LogIndex,
	})

	// Feed the reply through the observer's real handler and the node-level
	// pending-read registry.
	observer.Handle(observerReply)
	ready := consumeObserverReady(t, observer, reads4)
	reads4.applied(observerReply.LogIndex)
	batch, exists := reads4.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	readyCtxLow := uint64(0)
	readyIndex := uint64(0)
	if len(ready) > 0 {
		readyCtxLow = ready[0].SystemCtx.Low
		readyIndex = ready[0].Index
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "observer_read_completion_state",
		"request_id":            "observer-read-A",
		"ready_count":           len(ready),
		"ready_ctx_low":         readyCtxLow,
		"ready_index":           readyIndex,
		"applied_index":         observerReply.LogIndex,
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"completed_after_reply": completedFlag(req4),
	})

	// A late confirmation of the observer's own context cannot repair it: the
	// leader already removed the queued entry.
	if heartbeatA, ok := findAssuranceMessage(
		leaderMessagesA, pb.Heartbeat, 2, ctxA.Low); ok {
		lateOutputs := c.deliverTo(1, c.deliver(heartbeatA))
		correct := 0
		for _, message := range lateOutputs {
			if message.Type == pb.ReadIndexResp && message.To == 4 &&
				message.Hint == ctxA.Low && message.HintHigh == ctxA.High {
				correct++
			}
		}
		emitObserverEndpointEvent(t, map[string]interface{}{
			"event":                       "observer_late_confirmation",
			"request_id":                  "observer-read-A",
			"context_correct_reply_count": correct,
			"completed_after_late_reply":  completedFlag(req4),
		})
	}
}

// TestAssuranceRemovedVoterCannotConfirmReadIndex applies a real RemoveNode for
// node 3 on the remaining voters, queues a read at the leader, and then delivers
// the confirming heartbeat response first from the removed node and then from a
// current voter, recording how many replies each delivery produces.
func TestAssuranceRemovedVoterCannotConfirmReadIndex(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}
	for _, id := range []uint64{1, 2} {
		c.peers[id].ApplyConfigChange(pb.ConfigChange{
			Type:   pb.RemoveNode,
			NodeID: 3,
		})
		if messages := c.pump(id); len(messages) > 0 {
			c.drain(messages)
		}
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":        "voter_removed",
		"removed_node": uint64(3),
		"voters":       []uint64{1, 2},
	})

	ctx := pb.SystemCtx{Low: 303, High: 3003}
	c.peers[2].ReadIndex(ctx)
	_ = c.deliverTo(1, c.pump(2))
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "node2-read-R",
		"node_id":    uint64(2),
		"ctx_low":    ctx.Low,
	})

	c.peers[1].Handle(pb.Message{
		From:     3,
		To:       1,
		Type:     pb.HeartbeatResp,
		Hint:     ctx.Low,
		HintHigh: ctx.High,
	})
	removedOutputs := c.pump(1)
	removedReplies := 0
	for _, message := range removedOutputs {
		if message.Type == pb.ReadIndexResp && message.To == 2 {
			removedReplies++
		}
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":        "removed_voter_response",
		"request_id":   "node2-read-R",
		"sender":       uint64(3),
		"replies_to_2": removedReplies,
	})

	c.peers[1].Handle(pb.Message{
		From:     2,
		To:       1,
		Type:     pb.HeartbeatResp,
		Hint:     ctx.Low,
		HintHigh: ctx.High,
	})
	voterOutputs := c.pump(1)
	voterReplies := 0
	for _, message := range voterOutputs {
		if message.Type == pb.ReadIndexResp && message.To == 2 {
			voterReplies++
		}
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":        "current_voter_response",
		"request_id":   "node2-read-R",
		"sender":       uint64(2),
		"replies_to_2": voterReplies,
	})
}

func TestAssuranceObserverLocalReadIndexControl(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}
	registerAssuranceObserver(t, c)
	observer := newAssuranceObserver(t)

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads4 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req4, err := reads4.read(50)
	if err != nil {
		t.Fatalf("failed to create observer read: %v", err)
	}
	ctxA := reads4.nextCtx()
	ctxB := pb.SystemCtx{Low: 202, High: 2003}

	forwardedA := admitObserverRead(t, observer, reads4, req4, ctxA)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "control_observer_local_readindex_forwarded",
		"request_id": "control-observer-read-A",
		"node_id":    uint64(4),
		"leader_id":  forwardedA.To,
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})
	leaderMessagesA := c.deliver(forwardedA)
	c.peers[3].ReadIndex(ctxB)
	_ = c.deliverTo(1, c.pump(3))

	// Confirm the observer's own admitted context first.
	heartbeatA, ok := findAssuranceMessage(leaderMessagesA, pb.Heartbeat, 2, ctxA.Low)
	if !ok {
		t.Fatalf("no heartbeat carrying the observer context was sent to node 2; messages=%+v",
			leaderMessagesA)
	}
	leaderReplies := c.deliverTo(1, c.deliver(heartbeatA))
	observerReply, ok := findAssuranceMessage(leaderReplies, pb.ReadIndexResp, 4, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for observer 4; messages=%+v",
			leaderReplies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "control_observer_readindex_reply",
		"request_id":         "control-observer-read-A",
		"reply_to":           observerReply.To,
		"admitted_ctx_low":   ctxA.Low,
		"admitted_ctx_high":  ctxA.High,
		"trigger_from":       uint64(2),
		"response_ctx_low":   observerReply.Hint,
		"response_ctx_high":  observerReply.HintHigh,
		"response_log_index": observerReply.LogIndex,
	})

	observer.Handle(observerReply)
	ready := consumeObserverReady(t, observer, reads4)
	reads4.applied(observerReply.LogIndex)
	batch, exists := reads4.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	readyIndex := uint64(0)
	if len(ready) > 0 {
		readyIndex = ready[0].Index
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "control_observer_read_completion_state",
		"request_id":            "control-observer-read-A",
		"ready_count":           len(ready),
		"ready_index":           readyIndex,
		"applied_index":         observerReply.LogIndex,
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"completed_after_reply": completedFlag(req4),
	})
}

// TestAssurancePeriodicHeartbeatReadIndexBatching exercises the leader's own
// periodic heartbeat instead of a harness-chosen delivery: two reads from two
// followers are queued, one leader tick makes the heartbeat carry the newest
// queued context, and the earlier requester receives the reply produced by
// that confirmation.
func TestAssurancePeriodicHeartbeatReadIndexBatching(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads2 := newPendingReadIndex(pool, newReadIndexQueue(16))
	reads3 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req2, err := reads2.read(50)
	if err != nil {
		t.Fatalf("failed to create node 2 read: %v", err)
	}
	req3, err := reads3.read(50)
	if err != nil {
		t.Fatalf("failed to create node 3 read: %v", err)
	}
	ctxA := reads2.nextCtx()
	ctxB := reads3.nextCtx()
	reads2.add(ctxA, []*RequestState{req2})
	reads3.add(ctxB, []*RequestState{req3})

	// Both reads reach the leader through the real follower forwarding path.
	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	c.peers[3].ReadIndex(ctxB)
	_ = c.deliverTo(1, c.pump(3))
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "node2-read-A",
		"node_id":    uint64(2),
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "node3-read-B",
		"node_id":    uint64(3),
		"ctx_low":    ctxB.Low,
		"ctx_high":   ctxB.High,
	})

	// A single leader tick makes the periodic heartbeat carry the newest
	// queued context; no message is reordered by the harness.
	c.peers[1].Tick()
	periodic := c.pump(1)
	heartbeat, ok := findAssuranceMessage(periodic, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("periodic heartbeat did not carry the newest queued context; messages=%+v",
			periodic)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":             "periodic_heartbeat_broadcast",
		"heartbeat_to":      heartbeat.To,
		"heartbeat_ctx_low": heartbeat.Hint,
		"earlier_ctx_low":   ctxA.Low,
		"newest_ctx_low":    ctxB.Low,
		"queued_reads":      2,
	})

	replies := c.deliverTo(1, c.deliver(heartbeat))
	node2Reply, ok := findAssuranceMessage(replies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for node 2; messages=%+v",
			replies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "readindex_reply",
		"request_id":         "node2-read-A",
		"reply_to":           node2Reply.To,
		"admitted_ctx_low":   ctxA.Low,
		"response_ctx_low":   node2Reply.Hint,
		"response_ctx_high":  node2Reply.HintHigh,
		"response_log_index": node2Reply.LogIndex,
	})

	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	batch, exists := reads2.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	appliedIndex := uint64(0)
	if len(c.ready[2]) > 0 {
		appliedIndex = c.ready[2][0].Index
	}
	reads2.applied(appliedIndex)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "read_completion_state",
		"request_id":            "node2-read-A",
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"ready_index":           appliedIndex,
		"applied_index":         appliedIndex,
		"completed_after_reply": completedFlag(req2),
	})
	_ = req3
}

// TestAssurancePeriodicHeartbeatReadIndexControl queues a single read so the
// periodic heartbeat carries that read's own context, and checks that the same
// tick-driven path completes it.
func TestAssurancePeriodicHeartbeatReadIndexControl(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads2 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req2, err := reads2.read(50)
	if err != nil {
		t.Fatalf("failed to create node 2 read: %v", err)
	}
	ctxA := reads2.nextCtx()
	reads2.add(ctxA, []*RequestState{req2})
	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "control_readindex_queued",
		"request_id": "control-node2-A",
		"node_id":    uint64(2),
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})

	c.peers[1].Tick()
	periodic := c.pump(1)
	heartbeat, ok := findAssuranceMessage(periodic, pb.Heartbeat, 2, ctxA.Low)
	if !ok {
		t.Fatalf("periodic heartbeat did not carry the only queued context; messages=%+v",
			periodic)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":             "control_periodic_heartbeat_broadcast",
		"heartbeat_to":      heartbeat.To,
		"heartbeat_ctx_low": heartbeat.Hint,
		"queued_reads":      1,
	})

	replies := c.deliverTo(1, c.deliver(heartbeat))
	node2Reply, ok := findAssuranceMessage(replies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for node 2; messages=%+v",
			replies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "control_readindex_reply",
		"request_id":         "control-node2-A",
		"reply_to":           node2Reply.To,
		"admitted_ctx_low":   ctxA.Low,
		"response_ctx_low":   node2Reply.Hint,
		"response_log_index": node2Reply.LogIndex,
	})

	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	batch, exists := reads2.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	appliedIndex := uint64(0)
	if len(c.ready[2]) > 0 {
		appliedIndex = c.ready[2][0].Index
	}
	reads2.applied(appliedIndex)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "control_read_completion_state",
		"request_id":            "control-node2-A",
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"ready_index":           appliedIndex,
		"applied_index":         appliedIndex,
		"completed_after_reply": completedFlag(req2),
	})
}

// TestAssuranceLocalAndRemoteReadIndexOneConfirmation queues an earlier remote
// read and a later leader-local read, then lets the leader's ordinary broadcast
// for the local read confirm both, and compares what each requester receives.
func TestAssuranceLocalAndRemoteReadIndexOneConfirmation(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads2 := newPendingReadIndex(pool, newReadIndexQueue(16))
	reads1 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req2, err := reads2.read(50)
	if err != nil {
		t.Fatalf("failed to create remote read: %v", err)
	}
	req1, err := reads1.read(50)
	if err != nil {
		t.Fatalf("failed to create local read: %v", err)
	}
	ctxA := reads2.nextCtx()
	ctxL := reads1.nextCtx()
	reads2.add(ctxA, []*RequestState{req2})
	reads1.add(ctxL, []*RequestState{req1})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "remote-read-A",
		"node_id":    uint64(2),
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "local-read-L",
		"node_id":    uint64(1),
		"ctx_low":    ctxL.Low,
		"ctx_high":   ctxL.High,
	})

	// The earlier remote read reaches the leader first.
	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	// The later leader-local read is queued behind it and the leader broadcasts
	// its own context immediately, as handleLeaderReadIndex does.
	c.peers[1].ReadIndex(ctxL)
	localMessages := c.pump(1)
	heartbeat, ok := findAssuranceMessage(localMessages, pb.Heartbeat, 3, ctxL.Low)
	if !ok {
		t.Fatalf("leader did not broadcast its local read context; messages=%+v",
			localMessages)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":             "confirmation_broadcast",
		"heartbeat_to":      heartbeat.To,
		"heartbeat_ctx_low": heartbeat.Hint,
		"earlier_ctx_low":   ctxA.Low,
		"local_ctx_low":     ctxL.Low,
		"queued_reads":      2,
	})

	replies := c.deliverTo(1, c.deliver(heartbeat))
	node2Reply, ok := findAssuranceMessage(replies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for node 2; messages=%+v",
			replies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "remote_readindex_reply",
		"request_id":         "remote-read-A",
		"reply_to":           node2Reply.To,
		"admitted_ctx_low":   ctxA.Low,
		"response_ctx_low":   node2Reply.Hint,
		"response_log_index": node2Reply.LogIndex,
	})

	// The leader's own read finishes through the local ready-to-read path.
	reads1.addReady(c.ready[1])
	localBatch, localExists := reads1.batches[ctxL]
	localBatchIndex := uint64(0)
	if localExists {
		localBatchIndex = localBatch.index
	}
	reads1.applied(node2Reply.LogIndex)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "local_read_completion_state",
		"request_id":            "local-read-L",
		"original_batch_exists": localExists,
		"original_batch_index":  localBatchIndex,
		"applied_index":         node2Reply.LogIndex,
		"completed_after_reply": completedFlag(req1),
	})

	// The earlier remote requester consumes the same reply.
	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	remoteBatch, remoteExists := reads2.batches[ctxA]
	remoteBatchIndex := uint64(0)
	if remoteExists {
		remoteBatchIndex = remoteBatch.index
	}
	reads2.applied(node2Reply.LogIndex)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "remote_read_completion_state",
		"request_id":            "remote-read-A",
		"original_batch_exists": remoteExists,
		"original_batch_index":  remoteBatchIndex,
		"applied_index":         node2Reply.LogIndex,
		"completed_after_reply": completedFlag(req2),
	})
}

// TestAssuranceSeveralRemoteReadsOneConfirmation queues three remote reads from
// two nodes, lets one leader tick confirm the newest of them, and records which
// admitted reads complete.
func TestAssuranceSeveralRemoteReadsOneConfirmation(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads2a := newPendingReadIndex(pool, newReadIndexQueue(16))
	reads3 := newPendingReadIndex(pool, newReadIndexQueue(16))
	reads2c := newPendingReadIndex(pool, newReadIndexQueue(16))
	req2a, err := reads2a.read(50)
	if err != nil {
		t.Fatalf("failed to create node 2 earlier read: %v", err)
	}
	req3, err := reads3.read(50)
	if err != nil {
		t.Fatalf("failed to create node 3 read: %v", err)
	}
	req2c, err := reads2c.read(50)
	if err != nil {
		t.Fatalf("failed to create node 2 later read: %v", err)
	}
	ctxA := reads2a.nextCtx()
	ctxB := reads3.nextCtx()
	ctxC := reads2c.nextCtx()
	reads2a.add(ctxA, []*RequestState{req2a})
	reads3.add(ctxB, []*RequestState{req3})
	reads2c.add(ctxC, []*RequestState{req2c})

	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	c.peers[3].ReadIndex(ctxB)
	_ = c.deliverTo(1, c.pump(3))
	c.peers[2].ReadIndex(ctxC)
	_ = c.deliverTo(1, c.pump(2))
	for _, item := range []struct {
		id  string
		nid uint64
		ctx pb.SystemCtx
	}{
		{"read-A", 2, ctxA},
		{"read-B", 3, ctxB},
		{"read-C", 2, ctxC},
	} {
		emitObserverEndpointEvent(t, map[string]interface{}{
			"event":      "readindex_queued",
			"request_id": item.id,
			"node_id":    item.nid,
			"ctx_low":    item.ctx.Low,
		})
	}

	c.peers[1].Tick()
	periodic := c.pump(1)
	heartbeat, ok := findAssuranceMessage(periodic, pb.Heartbeat, 3, ctxC.Low)
	if !ok {
		t.Fatalf("periodic heartbeat did not carry the newest context; messages=%+v",
			periodic)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":             "periodic_heartbeat_broadcast",
		"heartbeat_to":      heartbeat.To,
		"heartbeat_ctx_low": heartbeat.Hint,
		"queued_reads":      3,
	})

	replies := c.deliverTo(1, c.deliver(heartbeat))
	var node2Replies []pb.Message
	var node3Reply pb.Message
	var hasNode3 bool
	for _, message := range replies {
		if message.Type != pb.ReadIndexResp {
			continue
		}
		if message.To == 2 {
			node2Replies = append(node2Replies, message)
		}
		if message.To == 3 {
			node3Reply = message
			hasNode3 = true
		}
	}
	if len(node2Replies) == 0 || !hasNode3 {
		t.Fatalf("missing replies; node2=%d node3=%v messages=%+v",
			len(node2Replies), hasNode3, replies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "read_a_reply",
		"request_id":         "read-A",
		"reply_to":           node2Replies[0].To,
		"admitted_ctx_low":   ctxA.Low,
		"response_ctx_low":   node2Replies[0].Hint,
		"response_log_index": node2Replies[0].LogIndex,
	})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "read_c_reply",
		"request_id":         "read-C",
		"reply_to":           node2Replies[len(node2Replies)-1].To,
		"admitted_ctx_low":   ctxC.Low,
		"response_ctx_low":   node2Replies[len(node2Replies)-1].Hint,
		"response_log_index": node2Replies[len(node2Replies)-1].LogIndex,
	})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "read_b_reply",
		"request_id":         "read-B",
		"reply_to":           node3Reply.To,
		"admitted_ctx_low":   ctxB.Low,
		"response_ctx_low":   node3Reply.Hint,
		"response_log_index": node3Reply.LogIndex,
	})

	appliedIndex := node2Replies[0].LogIndex
	for i := range node2Replies {
		_ = c.deliver(node2Replies[i])
	}
	_ = c.deliver(node3Reply)
	reads2a.addReady(c.ready[2])
	reads2c.addReady(c.ready[2])
	reads3.addReady(c.ready[3])
	reads2a.applied(appliedIndex)
	reads2c.applied(appliedIndex)
	reads3.applied(appliedIndex)
	for _, item := range []struct {
		id    string
		event string
		req   *RequestState
		reg   *pendingReadIndex
		ctx   pb.SystemCtx
	}{
		{"read-A", "read_a_completion", req2a, reads2a, ctxA},
		{"read-B", "read_b_completion", req3, reads3, ctxB},
		{"read-C", "read_c_completion", req2c, reads2c, ctxC},
	} {
		batch, exists := item.reg.batches[item.ctx]
		batchIndex := uint64(0)
		if exists {
			batchIndex = batch.index
		}
		emitObserverEndpointEvent(t, map[string]interface{}{
			"event":                 item.event,
			"request_id":            item.id,
			"original_batch_exists": exists,
			"original_batch_index":  batchIndex,
			"applied_index":         appliedIndex,
			"completed_after_reply": completedFlag(item.req),
		})
	}
}

// TestAssuranceSecondConfigChangeDroppedWhilePending proposes two configuration
// changes at a live leader without applying the first, and records what the
// leader saves and reports dropped for each proposal.
func TestAssuranceSecondConfigChangeDroppedWhilePending(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	c.peers[1].ProposeConfigChange(pb.ConfigChange{
		Type:           pb.AddNode,
		NodeID:         4,
		Address:        "assurance-4",
		ConfigChangeId: 1,
	}, 9001)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":   "config_change_requested",
		"key":     uint64(9001),
		"node_id": uint64(4),
	})
	firstUpdate := c.pumpUpdate(1)
	firstConfig := 0
	for _, entry := range firstUpdate.EntriesToSave {
		if entry.Type == pb.ConfigChangeEntry {
			firstConfig++
		}
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                "first_config_change_proposed",
		"key":                  uint64(9001),
		"config_entries_saved": firstConfig,
		"dropped_entries":      len(firstUpdate.DroppedEntries),
	})

	c.peers[1].ProposeConfigChange(pb.ConfigChange{
		Type:           pb.AddNode,
		NodeID:         5,
		Address:        "assurance-5",
		ConfigChangeId: 2,
	}, 9002)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":   "config_change_requested",
		"key":     uint64(9002),
		"node_id": uint64(5),
	})
	secondUpdate := c.pumpUpdate(1)
	secondConfig := 0
	applicationEntries := 0
	for _, entry := range secondUpdate.EntriesToSave {
		switch entry.Type {
		case pb.ConfigChangeEntry:
			secondConfig++
		case pb.ApplicationEntry:
			applicationEntries++
		}
	}
	droppedKey := uint64(0)
	if len(secondUpdate.DroppedEntries) > 0 {
		droppedKey = secondUpdate.DroppedEntries[0].Key
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                     "second_config_change_proposed",
		"key":                       uint64(9002),
		"config_entries_saved":      secondConfig,
		"application_entries_saved": applicationEntries,
		"dropped_entries":           len(secondUpdate.DroppedEntries),
		"dropped_key":               droppedKey,
	})
}

// TestAssuranceStaleAndNewerSnapshotDelivery delivers an out-of-date snapshot
// and then a newer one to a follower, recording the snapshot the follower
// exposes and its committed index after each delivery.
func TestAssuranceStaleAndNewerSnapshotDelivery(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}
	membership := pb.Membership{
		ConfigChangeId: 1,
		Addresses: map[uint64]string{
			1: "assurance-1",
			2: "assurance-2",
			3: "assurance-3",
		},
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":   "snapshot_delivery_requested",
		"node_id": uint64(2),
		"index":   uint64(3),
	})
	c.peers[2].Handle(pb.Message{
		From: 1,
		To:   2,
		Type: pb.InstallSnapshot,
		Snapshot: pb.Snapshot{
			Index:      3,
			Term:       1,
			Membership: membership,
		},
	})
	staleUpdate := c.pumpUpdate(2)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":            "stale_snapshot_delivered",
		"index":            uint64(3),
		"snapshot_index":   staleUpdate.Snapshot.Index,
		"snapshot_present": !pb.IsEmptySnapshot(staleUpdate.Snapshot),
		"commit_after":     c.commit[2],
	})

	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":   "snapshot_delivery_requested",
		"node_id": uint64(2),
		"index":   uint64(10),
	})
	c.peers[2].Handle(pb.Message{
		From: 1,
		To:   2,
		Type: pb.InstallSnapshot,
		Snapshot: pb.Snapshot{
			Index:      10,
			Term:       2,
			Membership: membership,
		},
	})
	newerUpdate := c.pumpUpdate(2)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":            "newer_snapshot_delivered",
		"index":            uint64(10),
		"snapshot_index":   newerUpdate.Snapshot.Index,
		"snapshot_present": !pb.IsEmptySnapshot(newerUpdate.Snapshot),
		"commit_after":     c.commit[2],
	})
}

before.source:
package dragonboat

import (
	"encoding/json"
	"errors"
	"math"
	"sync"
	"testing"

	"github.com/lni/dragonboat/v3/config"
	dragonraft "github.com/lni/dragonboat/v3/internal/raft"
	pb "github.com/lni/dragonboat/v3/raftpb"
)

var (
	errAssuranceCompacted   = errors.New("assurance log compacted")
	errAssuranceOutOfDate   = errors.New("assurance snapshot out of date")
	errAssuranceUnavailable = errors.New("assurance log unavailable")
)

type assuranceLogDB struct {
	entries     []pb.Entry
	markerIndex uint64
	markerTerm  uint64
	snapshot    pb.Snapshot
	state       pb.State
}

func newAssuranceLogDB() *assuranceLogDB {
	return &assuranceLogDB{}
}

func (db *assuranceLogDB) firstIndex() uint64 {
	return db.markerIndex + 1
}

func (db *assuranceLogDB) lastIndex() uint64 {
	return db.markerIndex + uint64(len(db.entries))
}

func (db *assuranceLogDB) GetRange() (uint64, uint64) {
	return db.firstIndex(), db.lastIndex()
}

func (db *assuranceLogDB) SetRange(index uint64, length uint64) {}

func (db *assuranceLogDB) NodeState() (pb.State, pb.Membership) {
	return db.state, db.snapshot.Membership
}

func (db *assuranceLogDB) SetState(state pb.State) {
	db.state = state
}

func (db *assuranceLogDB) CreateSnapshot(snapshot pb.Snapshot) error {
	if db.snapshot.Index >= snapshot.Index {
		return errAssuranceOutOfDate
	}
	db.snapshot = snapshot
	return nil
}

func (db *assuranceLogDB) ApplySnapshot(snapshot pb.Snapshot) error {
	if db.snapshot.Index >= snapshot.Index {
		return errAssuranceOutOfDate
	}
	db.snapshot = snapshot
	db.markerIndex = snapshot.Index
	db.markerTerm = snapshot.Term
	db.entries = nil
	return nil
}

func (db *assuranceLogDB) Term(index uint64) (uint64, error) {
	if index == 0 {
		return 0, nil
	}
	if index == db.markerIndex {
		return db.markerTerm, nil
	}
	if index < db.firstIndex() {
		return 0, errAssuranceCompacted
	}
	if index > db.lastIndex() {
		return 0, errAssuranceUnavailable
	}
	return db.entries[index-db.firstIndex()].Term, nil
}

func (db *assuranceLogDB) Entries(low uint64, high uint64, maxSize uint64) ([]pb.Entry, error) {
	if low <= db.markerIndex {
		return nil, errAssuranceCompacted
	}
	if high > db.lastIndex()+1 {
		return nil, errAssuranceUnavailable
	}
	if low >= high {
		return nil, nil
	}
	entries := append([]pb.Entry(nil), db.entries[low-db.firstIndex():high-db.firstIndex()]...)
	if maxSize == math.MaxUint64 || len(entries) == 0 {
		return entries, nil
	}
	total := 0
	for i := range entries {
		total += entries[i].SizeUpperLimit()
		if uint64(total) > maxSize {
			return entries[:i], nil
		}
	}
	return entries, nil
}

func (db *assuranceLogDB) Snapshot() pb.Snapshot {
	return db.snapshot
}

func (db *assuranceLogDB) Compact(index uint64) error {
	return nil
}

func (db *assuranceLogDB) Append(entries []pb.Entry) error {
	if len(entries) == 0 {
		return nil
	}
	offset := entries[0].Index - db.markerIndex
	if uint64(len(db.entries)+1) > offset {
		db.entries = db.entries[:offset-1]
	}
	db.entries = append(db.entries, entries...)
	return nil
}

type assuranceCluster struct {
	peers   map[uint64]*dragonraft.Peer
	logs    map[uint64]*assuranceLogDB
	applied map[uint64]uint64
	commit  map[uint64]uint64
	ready   map[uint64][]pb.ReadyToRead
}

func newAssuranceCluster(t *testing.T) *assuranceCluster {
	t.Helper()
	c := &assuranceCluster{
		peers:   make(map[uint64]*dragonraft.Peer),
		logs:    make(map[uint64]*assuranceLogDB),
		applied: make(map[uint64]uint64),
		commit:  make(map[uint64]uint64),
		ready:   make(map[uint64][]pb.ReadyToRead),
	}
	addresses := []dragonraft.PeerAddress{
		{NodeID: 1, Address: "assurance-1"},
		{NodeID: 2, Address: "assurance-2"},
		{NodeID: 3, Address: "assurance-3"},
	}
	for id := uint64(1); id <= 3; id++ {
		db := newAssuranceLogDB()
		cfg := config.Config{
			ClusterID:       7,
			NodeID:          id,
			ElectionRTT:     10,
			HeartbeatRTT:    1,
			MaxInMemLogSize: 0,
		}
		c.logs[id] = db
		c.peers[id] = dragonraft.Launch(cfg, db, nil, addresses, true, true)
		c.applied[id] = uint64(len(addresses))
		c.peers[id].NotifyRaftLastApplied(c.applied[id])
	}
	return c
}

func (c *assuranceCluster) pump(id uint64) []pb.Message {
	update := c.pumpUpdate(id)
	return append([]pb.Message(nil), update.Messages...)
}

func (c *assuranceCluster) pumpUpdate(id uint64) pb.Update {
	update := c.peers[id].GetUpdate(true, c.applied[id])
	c.ready[id] = append(c.ready[id], update.ReadyToReads...)
	if update.State.Commit > c.commit[id] {
		c.commit[id] = update.State.Commit
	}
	if len(update.EntriesToSave) > 0 {
		if err := c.logs[id].Append(update.EntriesToSave); err != nil {
			panic(err)
		}
	}
	c.peers[id].Commit(update)
	return update
}

func (c *assuranceCluster) deliver(message pb.Message) []pb.Message {
	c.peers[message.To].Handle(message)
	return c.pump(message.To)
}

func (c *assuranceCluster) drain(messages []pb.Message) {
	queue := append([]pb.Message(nil), messages...)
	for len(queue) > 0 {
		message := queue[0]
		queue = queue[1:]
		queue = append(queue, c.deliver(message)...)
	}
}

func (c *assuranceCluster) deliverTo(id uint64, messages []pb.Message) []pb.Message {
	var produced []pb.Message
	for _, message := range messages {
		if message.To == id {
			produced = append(produced, c.deliver(message)...)
		}
	}
	return produced
}

func findAssuranceMessage(messages []pb.Message,
	messageType pb.MessageType, to uint64, hint uint64) (pb.Message, bool) {
	for _, message := range messages {
		if message.Type == messageType && message.To == to &&
			(hint == 0 || message.Hint == hint) {
			return message, true
		}
	}
	return pb.Message{}, false
}

func emitObserverEndpointEvent(t *testing.T, event map[string]interface{}) {
	t.Helper()
	b, err := json.Marshal(event)
	if err != nil {
		t.Fatalf("failed to marshal assurance event: %v", err)
	}
	t.Logf("CA_EVENT %s", b)
}

// registerAssuranceObserver records node 4 as an observer in every voter's
// raft membership, which is the state produced by an applied AddObserver
// config change.
func registerAssuranceObserver(t *testing.T, c *assuranceCluster) {
	t.Helper()
	for id := uint64(1); id <= 3; id++ {
		c.peers[id].ApplyConfigChange(pb.ConfigChange{
			Type:    pb.AddObserver,
			NodeID:  4,
			Address: "assurance-4",
		})
		if messages := c.pump(id); len(messages) > 0 {
			c.drain(messages)
		}
	}
	if c.commit[1] < 4 {
		t.Fatalf("observer registration disturbed the leader commit, commit=%d",
			c.commit[1])
	}
}

// newAssuranceObserver launches a real observer Raft peer for node 4. Its log
// DB carries the committed voter membership {1,2,3}, which is what an observer
// learns from the replicated bootstrap entries or a snapshot, and a leader
// heartbeat teaches it the current leader.
func newAssuranceObserver(t *testing.T) *dragonraft.Peer {
	t.Helper()
	db := newAssuranceLogDB()
	db.snapshot.Membership = pb.Membership{
		ConfigChangeId: 1,
		Addresses: map[uint64]string{
			1: "assurance-1",
			2: "assurance-2",
			3: "assurance-3",
		},
	}
	cfg := config.Config{
		ClusterID:       7,
		NodeID:          4,
		ElectionRTT:     10,
		HeartbeatRTT:    1,
		MaxInMemLogSize: 0,
		IsObserver:      true,
	}
	observer := dragonraft.Launch(cfg, db, nil, nil, false, true)
	observer.Handle(pb.Message{
		From: 1,
		To:   4,
		Type: pb.Heartbeat,
		Term: 1,
	})
	update := observer.GetUpdate(true, 0)
	observer.Commit(update)
	return observer
}

// admitObserverRead registers an observer-local ReadIndex request and returns
// the pending-read bookkeeping together with the ReadIndex message that the
// observer's real raft peer forwarded to its leader.
func admitObserverRead(t *testing.T, observer *dragonraft.Peer,
	reads *pendingReadIndex, req *RequestState,
	ctx pb.SystemCtx) pb.Message {
	t.Helper()
	reads.add(ctx, []*RequestState{req})
	observer.ReadIndex(ctx)
	update := observer.GetUpdate(true, 0)
	forwarded := append([]pb.Message(nil), update.Messages...)
	observer.Commit(update)
	message, ok := findAssuranceMessage(forwarded, pb.ReadIndex, 1, ctx.Low)
	if !ok {
		t.Fatalf("observer did not forward its ReadIndex request; messages=%+v",
			forwarded)
	}
	return message
}

// consumeObserverReady feeds the observer peer's real ReadyToRead output into
// the node-level pending read registry and returns the ready index.
func consumeObserverReady(t *testing.T, observer *dragonraft.Peer,
	reads *pendingReadIndex) []pb.ReadyToRead {
	t.Helper()
	update := observer.GetUpdate(true, 0)
	ready := append([]pb.ReadyToRead(nil), update.ReadyToReads...)
	observer.Commit(update)
	reads.addReady(ready)
	return ready
}

func completedFlag(req *RequestState) int {
	select {
	case <-req.CompletedC:
		return 1
	default:
		return 0
	}
}

func TestAssuranceObserverLocalReadIndexCompletion(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}
	registerAssuranceObserver(t, c)
	observer := newAssuranceObserver(t)

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads4 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req4, err := reads4.read(50)
	if err != nil {
		t.Fatalf("failed to create observer read: %v", err)
	}
	ctxA := reads4.nextCtx()
	ctxB := pb.SystemCtx{Low: 202, High: 2003}

	forwardedA := admitObserverRead(t, observer, reads4, req4, ctxA)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "observer_local_readindex_forwarded",
		"request_id": "observer-read-A",
		"node_id":    uint64(4),
		"leader_id":  forwardedA.To,
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})

	// The real leader admits the observer's forwarded request.
	leaderMessagesA := c.deliver(forwardedA)
	// A later voter-originated request is queued behind the observer's request.
	c.peers[3].ReadIndex(ctxB)
	leaderMessagesB := c.deliverTo(1, c.pump(3))
	if len(leaderMessagesB) == 0 {
		t.Fatal("leader produced no confirmation heartbeat for the later context")
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":            "later_voter_readindex_queued",
		"request_id":       "voter-read-B",
		"node_id":          uint64(3),
		"leader_id":        uint64(1),
		"ctx_low":          ctxB.Low,
		"ctx_high":         ctxB.High,
		"admitted_ctx_low": ctxA.Low,
	})

	heartbeatB, ok := findAssuranceMessage(leaderMessagesB, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("no heartbeat carrying the later context was sent to node 3; messages=%+v",
			leaderMessagesB)
	}
	node3Output := c.deliver(heartbeatB)
	leaderReplies := c.deliverTo(1, node3Output)
	observerReply, ok := findAssuranceMessage(leaderReplies, pb.ReadIndexResp, 4, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for observer 4; messages=%+v",
			leaderReplies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "observer_readindex_reply",
		"request_id":         "observer-read-A",
		"reply_to":           observerReply.To,
		"admitted_ctx_low":   ctxA.Low,
		"admitted_ctx_high":  ctxA.High,
		"trigger_from":       uint64(3),
		"trigger_ctx_low":    ctxB.Low,
		"trigger_ctx_high":   ctxB.High,
		"response_ctx_low":   observerReply.Hint,
		"response_ctx_high":  observerReply.HintHigh,
		"response_log_index": observerReply.LogIndex,
	})

	// Feed the reply through the observer's real handler and the node-level
	// pending-read registry.
	observer.Handle(observerReply)
	ready := consumeObserverReady(t, observer, reads4)
	reads4.applied(observerReply.LogIndex)
	batch, exists := reads4.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	readyCtxLow := uint64(0)
	readyIndex := uint64(0)
	if len(ready) > 0 {
		readyCtxLow = ready[0].SystemCtx.Low
		readyIndex = ready[0].Index
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "observer_read_completion_state",
		"request_id":            "observer-read-A",
		"ready_count":           len(ready),
		"ready_ctx_low":         readyCtxLow,
		"ready_index":           readyIndex,
		"applied_index":         observerReply.LogIndex,
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"completed_after_reply": completedFlag(req4),
	})

	// A late confirmation of the observer's own context cannot repair it: the
	// leader already removed the queued entry.
	if heartbeatA, ok := findAssuranceMessage(
		leaderMessagesA, pb.Heartbeat, 2, ctxA.Low); ok {
		lateOutputs := c.deliverTo(1, c.deliver(heartbeatA))
		correct := 0
		for _, message := range lateOutputs {
			if message.Type == pb.ReadIndexResp && message.To == 4 &&
				message.Hint == ctxA.Low && message.HintHigh == ctxA.High {
				correct++
			}
		}
		emitObserverEndpointEvent(t, map[string]interface{}{
			"event":                       "observer_late_confirmation",
			"request_id":                  "observer-read-A",
			"context_correct_reply_count": correct,
			"completed_after_late_reply":  completedFlag(req4),
		})
	}
}

// TestAssuranceRemovedVoterCannotConfirmReadIndex applies a real RemoveNode for
// node 3 on the remaining voters, queues a read at the leader, and then delivers
