	c.peers[1].Handle(pb.Message{
		From:     2,
		To:       1,
		Type:     pb.HeartbeatResp,
		Hint:     ctx.Low,
		HintHigh: ctx.High,
	})
	voterOutputs := c.pump(1)
	voterReplies := 0
	for _, message := range voterOutputs {
		if message.Type == pb.ReadIndexResp && message.To == 2 {
			voterReplies++
		}
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":        "current_voter_response",
		"request_id":   "node2-read-R",
		"sender":       uint64(2),
		"replies_to_2": voterReplies,
	})
